cat > /tmp/m0_verify.c << 'EOF'
#include <stdio.h>
#include "include/epilog_ffi.h"

typedef struct { const char *name; int found; } BindResult;

static EpilogSignal on_solution(const EpilogSolution *soln, void *ud) {
    BindResult *r = (BindResult *)ud;
    uint32_t n = epilog_soln_var_count(soln);
    for (uint32_t i = 0; i < n; i++) {
        const char *vname = epilog_soln_var_name(soln, i);
        const char *val   = epilog_soln_var_atom(soln, i);
        if (vname && val) {
            printf("  %s = %s\n", vname, val);
        }
    }
    r->found++;
    return EPILOG_NEXT;
}

int main(void) {
    printf("Epilog %s — M0 acceptance test\n\n", epilog_version_string());

    EpilogEngine *e = epilog_create();

    epilog_load_string(e,
        "crushing(uriel, character_a)."
        "crushing(anna_croft, character_a)."
        "rivals(X, Y) :- crushing(X, Z), crushing(Y, Z), X \\= Y."
    );

    printf("?- rivals(uriel, anna_croft).\n");
    BindResult r1 = {0, 0};
    int n1 = epilog_query(e, "rivals(uriel, anna_croft)", on_solution, &r1);
    printf("  => %s (%d solution(s))\n\n", n1 > 0 ? "true" : "false", n1);

    printf("?- rivals(X, character_a).\n");
    BindResult r2 = {0, 0};
    int n2 = epilog_query(e, "rivals(X, character_a)", on_solution, &r2);
    printf("  => %s (%d solution(s))\n\n", n2 > 0 ? "true" : "false", n2);

    printf("?- rivals(X, Y).\n");
    BindResult r3 = {0, 0};
    int n3 = epilog_query(e, "rivals(X, Y)", on_solution, &r3);
    printf("  => %d solution(s)\n\n", n3);

    int pass = (n1 == 1) && (n2 == 0) && (n3 == 2);
    printf("M0 acceptance: %s\n", pass ? "PASS" : "FAIL");

    epilog_destroy(e);
    return pass ? 0 : 1;
}
EOF

