1	/*
2	 * epilog_ffi.cpp — C-linkage wrapper over the Epilog inference engine.
3	 *
4	 * Implements the API declared in epilog_ffi.h.  All internal C++ types are
5	 * hidden behind EpilogEngine and EpilogSolution, which are opaque to callers.
6	 */
7	
8	#include "../include/epilog_ffi.h"
9	#include "../include/atoms.hpp"
10	#include "../include/variables.hpp"
11	#include "../include/terms.hpp"
12	#include "../include/lexer.hpp"
13	#include "../include/parser.hpp"
14	#include "../include/database.hpp"
15	#include "../include/solver.hpp"
16	#include "../include/stats.hpp"
17	
18	#include <cstdio>
19	#include <cstdlib>
20	#include <cstring>
21	#include <new>
22	
23	/* ---- EpilogEngine -------------------------------------------------------- */
24	
25	struct EpilogEngine {
26	    AtomTable   atoms       = {};
27	    Database    db          = {};
28	    TermArena   clause_arena = {};
29	    VarRegistry clause_vars  = {};
30	    QueryStats  stats        = {};
31	};
32	
33	/* ---- EpilogSolution ------------------------------------------------------ */
34	
35	/*
36	 * A solution snapshot: for each query variable we store its name and its
37	 * resolved binding (kind + value).  This is populated from the SolverEnv
38	 * inside the solve callback before handing off to user code.
39	 */
40	
41	constexpr uint32_t FFI_MAX_VARS = VAR_REGISTRY_CAPACITY;
42	
43	struct SolnVar {
44	    char           name[VAR_NAME_MAX_LEN + 1U];
45	    EpilogTermKind kind    = EPILOG_TERM_UNBOUND;
46	    AtomId         atom_id = ATOM_ID_INVALID;   /* TERM_ATOM */
47	    int32_t        int_val = 0;                  /* TERM_INT  */
48	    AtomId         functor = ATOM_ID_INVALID;   /* TERM_COMPOUND */
49	    uint8_t        arity   = 0U;                 /* TERM_COMPOUND */
50	};
51	
52	struct EpilogSolution {
53	    const AtomTable *atoms    = nullptr;
54	    SolnVar          vars[FFI_MAX_VARS];
55	    uint32_t         var_count = 0U;
56	};
57	
58	/* ---- Internal helpers ---------------------------------------------------- */
59	
60	/*
61	 * resolve_term — walk the term/variable chain and classify into SolnVar.
62	 */
63	static void resolve_term(SolnVar *out, TermRef ref,
64	                         const TermArena *arena, const VarRegistry *vars,
65	                         const AtomTable *atoms)
66	{
67	    /* Follow variable bindings */
68	    for (uint32_t step = 0U; step < VAR_REGISTRY_CAPACITY; ++step) {
69	        const Term *t = term_get(arena, ref);
70	        if (t == nullptr) { out->kind = EPILOG_TERM_UNBOUND; return; }
71	
72	        switch (t->kind) {
73	            case TERM_KIND_ATOM:
74	                out->kind    = EPILOG_TERM_ATOM;
75	                out->atom_id = t->data.atom_id;
76	                return;
77	            case TERM_KIND_INT:
78	                out->kind    = EPILOG_TERM_INT;
79	                out->int_val = t->data.int_val;
80	                return;
81	            case TERM_KIND_COMPOUND:
82	                out->kind    = EPILOG_TERM_COMPOUND;
83	                out->functor = t->data.compound.functor;
84	                out->arity   = t->data.compound.arity;
85	                return;
86	            case TERM_KIND_VAR: {
87	                WalkResult wr = var_walk(vars, t->data.var.var_id);
88	                if (wr.tag == TERM_UNBOUND) {
89	                    out->kind = EPILOG_TERM_UNBOUND;
90	                    return;
91	                }
92	                if (wr.tag == TERM_TERMREF) {
93	                    ref = wr.value.term_ref;
94	                    break;
95	                }
96	                if (wr.tag == TERM_ATOM) {
97	                    out->kind    = EPILOG_TERM_ATOM;
98	                    out->atom_id = wr.value.atom_id;
99	                    return;
100	                }
101	                out->kind = EPILOG_TERM_UNBOUND;
102	                return;
103	            }
104	            default:
105	                out->kind = EPILOG_TERM_UNBOUND;
106	                return;
107	        }
108	    }
109	    (void)atoms;
110	    out->kind = EPILOG_TERM_UNBOUND;
111	}
112	
113	/* ---- Internal query state passed through solve callback ------------------ */
114	
115	struct QueryCtx {
116	    EpilogEngine   *engine       = nullptr;
117	    EpilogCallback  user_cb      = nullptr;
118	    void           *user_data    = nullptr;
119	    EpilogSolution  soln         = {};
120	    const TermArena *query_arena = nullptr;
121	    const VarRegistry *query_vars = nullptr;
122	    AtomId          top_functor  = ATOM_ID_INVALID;
123	    uint8_t         top_arity    = 0U;
124	    uint32_t        solutions    = 0U;
125	};
126	
127	static SolveSignal ffi_solve_callback(SolverEnv *env,
128	                                      const TermRef *goals,
129	                                      uint32_t goal_count,
130	                                      void *userdata)
131	{
132	    (void)goals; (void)goal_count;
133	    QueryCtx *qctx = static_cast<QueryCtx *>(userdata);
134	
135	    /* Build solution snapshot */
136	    EpilogSolution *soln = &qctx->soln;
137	    soln->atoms     = &qctx->engine->atoms;
138	    soln->var_count = 0U;
139	
140	    for (uint32_t i = 0U; i < env->vars->count && soln->var_count < FFI_MAX_VARS; ++i) {
141	        const VarEntry *ve = &env->vars->entries[i];
142	        if (ve->id == VAR_ID_INVALID) { continue; }
143	
144	        /* Skip anonymous variables */
145	        if (ve->name[0] == '_' && ve->name[1] == '\0') { continue; }
146	        /* Skip internal rename copies (contain '#' or other non-alpha prefix) */
147	        if (ve->name[0] == '\0') { continue; }
148	
149	        SolnVar *sv = &soln->vars[soln->var_count];
150	        memset(sv, 0, sizeof(SolnVar));
151	        memcpy(sv->name, ve->name, VAR_NAME_MAX_LEN);
152	        sv->name[VAR_NAME_MAX_LEN] = '\0';
153	
154	        /* Resolve binding */
155	        if (ve->tag == TERM_UNBOUND) {
156	            sv->kind = EPILOG_TERM_UNBOUND;
157	        } else if (ve->tag == TERM_ATOM) {
158	            sv->kind    = EPILOG_TERM_ATOM;
159	            sv->atom_id = ve->value.atom_id;
160	        } else if (ve->tag == TERM_TERMREF) {
161	            TermRef bound_ref = ve->value.term_ref;
162	            resolve_term(sv, bound_ref, env->arena, env->vars, &qctx->engine->atoms);
163	        } else {
164	            sv->kind = EPILOG_TERM_UNBOUND;
165	        }
166	
167	        soln->var_count++;
168	    }
169	
170	    qctx->solutions++;
171	
172	    if (qctx->user_cb == nullptr) { return SOLVE_NEXT; }
173	
174	    EpilogSignal sig = qctx->user_cb(soln, qctx->user_data);
175	    return (sig == EPILOG_STOP) ? SOLVE_STOP : SOLVE_NEXT;
176	}
