/*
 * main.odin — DMLS entry point.
 *
 * Phase 1 (skeleton): initialises Epilog, runs the bridge smoke test,
 * then exits cleanly.  Raylib and the simulation loop are added in Phase 2+.
 */

package dmls

import "core:fmt"
import "core:c"
import "core:os"

/* ---- Bridge smoke-test state --------------------------------------------- */

BridgeSmokeCtx :: struct {
    found_bob:  bool,
    found_carol: bool,
    solution_count: int,
}

smoke_callback :: proc "c" (soln: ^EpilogSolution, userdata: rawptr) -> EpilogSignal {
    ctx := cast(^BridgeSmokeCtx)userdata

    n := epilog_soln_var_count(soln)
    for i in 0..<n {
        name := epilog_soln_var_name(soln, i)
        val  := epilog_soln_var_atom(soln, i)
        if name != nil && val != nil {
            if string(val) == "bob"   { ctx.found_bob   = true }
            if string(val) == "carol" { ctx.found_carol = true }
        }
    }
    ctx.solution_count += 1
    return .EPILOG_NEXT
}

/* ---- Bridge smoke test ---------------------------------------------------- */

run_bridge_smoke_test :: proc() -> bool {
    fmt.println("=== Bridge smoke test ===")
    fmt.printf("Epilog version: %s\n\n", epilog_version_string())

    e := epilog_create()
    if e == nil {
        fmt.eprintln("FAIL: epilog_create() returned nil")
        return false
    }
    defer epilog_destroy(e)

    /* Assert facts */
    epilog_load_string(e, "parent(alice, bob).")
    epilog_load_string(e, "parent(bob, carol).")
    epilog_load_string(e, "grandparent(X, Y) :- parent(X, Z), parent(Z, Y).")

    /* Query 1: ground fact lookup */
    n1 := epilog_query(e, "parent(alice, bob)", nil, nil)
    fmt.printf("parent(alice, bob): %d solution(s)\n", n1)
    if n1 != 1 {
        fmt.eprintln("FAIL: expected 1 solution for ground fact")
        return false
    }

    /* Query 2: variable binding */
    ctx: BridgeSmokeCtx
    n2 := epilog_query(e, "grandparent(alice, X)", smoke_callback, &ctx)
    fmt.printf("grandparent(alice, X): %d solution(s)\n", n2)
