/*
 * creation.odin — Character creation screen (M2).
 *
 * Screen flow:
 *   Creation → Confirm → Relationship seeding → back to Residents / Simulation
 *
 * All drawing uses Raylib directly — no external UI framework.
 */

package dmls

import rl "vendor:raylib"
import "core:strings"
import "core:fmt"
import "core:mem"

// ---- Layout constants ------------------------------------------------------

SCREEN_W :: 1024
SCREEN_H ::  720

UI_PAD   :: 24
UI_LPAD  :: 64          // left margin for form fields
UI_FSIZE :: 20          // font size for body text
UI_HSIZE :: 28          // font size for headings
UI_SMALL :: 16

COL_BG      :: rl.Color{15,  15,  20,  255}
COL_PANEL   :: rl.Color{28,  28,  38,  255}
COL_ACCENT  :: rl.Color{120, 80,  200, 255}
COL_ACCENT2 :: rl.Color{200, 80,  120, 255}
COL_TEXT    :: rl.Color{220, 220, 230, 255}
COL_MUTED   :: rl.Color{130, 130, 150, 255}
COL_INPUT   :: rl.Color{40,  40,  55,  255}
COL_HOVER   :: rl.Color{60,  60,  80,  255}
COL_SELECT  :: rl.Color{90,  60,  160, 255}
COL_CONFIRM :: rl.Color{60,  160, 100, 255}

// ---- Input field -----------------------------------------------------------

InputField :: struct {
    buf    : [MAX_NAME_LEN]u8,
    len    : int,
    active : bool,
}

input_field_init :: proc(f: ^InputField) { f^ = {} }

input_field_str :: proc(f: ^InputField) -> string {
    return string(f.buf[:f.len])
}

input_field_update :: proc(f: ^InputField) {
    if !f.active do return
    ch := rl.GetCharPressed()
    for ch != 0 {
        if ch >= 32 && ch < 127 && f.len < MAX_NAME_LEN - 1 {
            f.buf[f.len] = u8(ch)
            f.len += 1
        }
        ch = rl.GetCharPressed()
    }
    if rl.IsKeyPressed(.BACKSPACE) && f.len > 0 {
        f.len -= 1
        f.buf[f.len] = 0
    }
}

input_field_draw :: proc(f: ^InputField, x, y, w, h: i32, label: cstring) {
    bg := COL_INPUT
    if f.active do bg = rl.Color{55, 50, 80, 255}
    rl.DrawRectangle(x, y, w, h, bg)
    rl.DrawRectangleLines(x, y, w, h, f.active ? COL_ACCENT : COL_MUTED)
    rl.DrawText(label, x, y - UI_SMALL - 4, UI_SMALL, COL_MUTED)

    text_buf: [MAX_NAME_LEN + 2]u8
    copy(text_buf[:], f.buf[:f.len])
    if f.active && (int(rl.GetTime() * 2) % 2 == 0) {
        text_buf[f.len] = '|'
        text_buf[f.len + 1] = 0
    } else {
        text_buf[f.len] = 0
    }
    rl.DrawText(cstring(raw_data(text_buf[:])), x + 8, y + (h - UI_FSIZE) / 2, UI_FSIZE, COL_TEXT)
}

// ---- Chip selector (cycles through options on click) -----------------------

chip_selector_draw :: proc(
    label: cstring,
    options: []cstring,
    selected: ^int,
    x, y, w: i32,
) -> bool {
    changed := false
    rl.DrawText(label, x, y, UI_SMALL, COL_MUTED)
    y2 := y + UI_SMALL + 6
    cx := x
    for opt, i in options {
        tw  := rl.MeasureText(opt, UI_FSIZE) + 24
        rect := rl.Rectangle{f32(cx), f32(y2), f32(tw), 34}
        hov  := rl.CheckCollisionPointRec(rl.GetMousePosition(), rect)
        bg   := i == selected^ ? COL_SELECT : (hov ? COL_HOVER : COL_INPUT)
        rl.DrawRectangleRec(rect, bg)
        rl.DrawRectangleLinesEx(rect, 1, i == selected^ ? COL_ACCENT : COL_MUTED)
        rl.DrawText(opt, cx + 12, y2 + 7, UI_FSIZE, COL_TEXT)
        if hov && rl.IsMouseButtonPressed(.LEFT) {
            selected^ = i
            changed = true
        }
        cx += tw + 8
        if cx > x + w - 100 { cx = x; y2 += 42 }
    }
    return changed
}

// ---- Sprite selector -------------------------------------------------------

SPRITE_COUNT :: 8

sprite_selector_draw :: proc(selected: ^u32, x, y: i32) {
    rl.DrawText("Sprite", x, y, UI_SMALL, COL_MUTED)
    for i in 0..<SPRITE_COUNT {
        sx   := x + i32(i) * 44
        sy   := y + 24
        rect := rl.Rectangle{f32(sx), f32(sy), 36, 36}
        hov  := rl.CheckCollisionPointRec(rl.GetMousePosition(), rect)
        sel  := u32(i) == selected^
        bg   := sel ? COL_SELECT : (hov ? COL_HOVER : COL_INPUT)
        rl.DrawRectangleRec(rect, bg)
        rl.DrawRectangleLinesEx(rect, 1, sel ? COL_ACCENT : COL_MUTED)
        // Sprite placeholder: coloured square with index number
        hue := f32(i) / f32(SPRITE_COUNT)
        r   := u8(80 + 100 * (1 - hue))
        g   := u8(80 + 100 * hue)
        b   := u8(180 - 80 * hue)
        rl.DrawRectangle(sx + 4, sy + 4, 28, 28, rl.Color{r, g, b, 200})
        num_buf: [4]u8
        n := fmt.bprintf(string(num_buf[:]), "%d", i + 1)
        num_buf[n] = 0
        rl.DrawText(cstring(raw_data(num_buf[:])), sx + 12, sy + 10, UI_SMALL, COL_TEXT)
        if hov && rl.IsMouseButtonPressed(.LEFT) {
            selected^ = u32(i)
        }
    }
}

// ---- Creation screen state -------------------------------------------------

CreationScreen :: struct {
    name_field     : InputField,
    nick_field     : InputField,
    age            : u8,
    gender_sel     : int,
    pref_sel       : int,
    personality_sel: int,
    pronouns_sel   : int,
    sprite_sel     : u32,
    show_confirm   : bool,
}

creation_screen_init :: proc(s: ^CreationScreen) {
    s^ = {}
    s.age = 20
    s.name_field.active = true
}

// Returns true when the user confirms creation.
// Fills `out` with the new character data.
creation_screen_update :: proc(s: ^CreationScreen, out: ^Character) -> bool {
    // Tab between fields
    if rl.IsKeyPressed(.TAB) {
        s.name_field.active = !s.name_field.active
        s.nick_field.active = !s.nick_field.active
    }
    if rl.IsKeyPressed(.ESCAPE) && s.show_confirm {
        s.show_confirm = false
    }

    input_field_update(&s.name_field)
    input_field_update(&s.nick_field)

    if s.show_confirm {
        return _draw_confirm(s, out)
    }
    return _draw_form(s)
}

_draw_form :: proc(s: ^CreationScreen) -> bool {
    rl.ClearBackground(COL_BG)

    // Header
    rl.DrawText("New Resident", UI_LPAD, UI_PAD, UI_HSIZE, COL_TEXT)
    rl.DrawText("Create a new island resident", UI_LPAD, UI_PAD + UI_HSIZE + 4, UI_SMALL, COL_MUTED)

    y := i32(UI_PAD + UI_HSIZE + 36)

    // Name / Nickname
    input_field_draw(&s.name_field, UI_LPAD, y, 320, 36, "Full name")
    if rl.CheckCollisionPointRec(rl.GetMousePosition(),
            rl.Rectangle{f32(UI_LPAD), f32(y), 320, 36}) &&
            rl.IsMouseButtonPressed(.LEFT) {
        s.name_field.active = true
        s.nick_field.active = false
    }

    input_field_draw(&s.nick_field, UI_LPAD + 340, y, 240, 36, "Nickname (what others call them)")
    if rl.CheckCollisionPointRec(rl.GetMousePosition(),
            rl.Rectangle{f32(UI_LPAD + 340), f32(y), 240, 36}) &&
            rl.IsMouseButtonPressed(.LEFT) {
        s.nick_field.active = true
        s.name_field.active = false
    }

    y += 70

    // Age with +/- buttons
    rl.DrawText("Age", UI_LPAD, y, UI_SMALL, COL_MUTED)
    y2 := y + UI_SMALL + 6
    minus_rect := rl.Rectangle{f32(UI_LPAD), f32(y2), 30, 30}
    plus_rect  := rl.Rectangle{f32(UI_LPAD + 80), f32(y2), 30, 30}
    rl.DrawRectangleRec(minus_rect, COL_INPUT)
    rl.DrawText("-", UI_LPAD + 9, y2 + 5, UI_FSIZE, COL_TEXT)
    age_buf: [8]u8
    n := fmt.bprintf(string(age_buf[:]), "%d", s.age)
    age_buf[n] = 0
    rl.DrawText(cstring(raw_data(age_buf[:])), UI_LPAD + 38, y2 + 5, UI_FSIZE, COL_TEXT)
    rl.DrawRectangleRec(plus_rect, COL_INPUT)
    rl.DrawText("+", UI_LPAD + 89, y2 + 5, UI_FSIZE, COL_TEXT)
    if rl.IsMouseButtonPressed(.LEFT) {
        mp := rl.GetMousePosition()
        if rl.CheckCollisionPointRec(mp, minus_rect) && s.age > 5   { s.age -= 1 }
        if rl.CheckCollisionPointRec(mp, plus_rect)  && s.age < 99  { s.age += 1 }
    }

    y += 64

    // Gender
    gender_opts := []cstring{"Male", "Female", "Nonbinary"}
    chip_selector_draw("Gender", gender_opts, &s.gender_sel, UI_LPAD, y, 600)
    y += 78

    // Dating preference
    pref_opts := []cstring{"Men", "Women", "Anyone", "Nobody"}
    chip_selector_draw("Dating preference", pref_opts, &s.pref_sel, UI_LPAD, y, 600)
    y += 78

    // Personality
    personality_opts := []cstring{
        "Ambitious Achiever", "Outgoing Merrymaker", "Outgoing Dynamo",
        "Laid-Back Guy", "Sweetie", "Cranky",
    }
    chip_selector_draw("Personality", personality_opts, &s.personality_sel, UI_LPAD, y, 900)
    y += 78

    // Pronouns
    pronoun_opts := []cstring{"he/him", "she/her", "they/them"}
    chip_selector_draw("Pronouns", pronoun_opts, &s.pronouns_sel, UI_LPAD, y, 400)
    y += 78

    // Sprite
    sprite_selector_draw(&s.sprite_sel, UI_LPAD, y)
    y += 80

    // Continue button
    cont_rect := rl.Rectangle{f32(UI_LPAD), f32(y), 200, 40}
    hov := rl.CheckCollisionPointRec(rl.GetMousePosition(), cont_rect)
    rl.DrawRectangleRec(cont_rect, hov ? COL_ACCENT : COL_INPUT)
    rl.DrawText("Continue ->", UI_LPAD + 16, y + 10, UI_FSIZE, COL_TEXT)
    if hov && rl.IsMouseButtonPressed(.LEFT) && s.name_field.len > 0 {
        s.show_confirm = true
    }

    return false
}

_draw_confirm :: proc(s: ^CreationScreen, out: ^Character) -> bool {
    rl.ClearBackground(COL_BG)

    // Dim overlay
    rl.DrawRectangle(0, 0, SCREEN_W, SCREEN_H, rl.Color{0, 0, 0, 120})

    pw, ph := i32(480), i32(380)
    px := (SCREEN_W - pw) / 2
    py := (SCREEN_H - ph) / 2

    rl.DrawRectangle(px, py, pw, ph, COL_PANEL)
    rl.DrawRectangleLines(px, py, pw, ph, COL_ACCENT)
    rl.DrawText("Does everything look good?", px + 20, py + 20, UI_HSIZE, COL_TEXT)

    lx := px + 20
    ly := py + 64

    rl.DrawText("Name:", lx, ly, UI_SMALL, COL_MUTED)
    name_cstr := strings.clone_to_cstring(input_field_str(&s.name_field), context.temp_allocator)
    rl.DrawText(name_cstr, lx + 100, ly, UI_SMALL, COL_TEXT)
    ly += 28

    nick := input_field_str(&s.nick_field)
    if len(nick) > 0 {
        rl.DrawText("Nickname:", lx, ly, UI_SMALL, COL_MUTED)
        nick_cstr := strings.clone_to_cstring(nick, context.temp_allocator)
        rl.DrawText(nick_cstr, lx + 100, ly, UI_SMALL, COL_TEXT)
        ly += 28
    }

    age_buf: [16]u8
    n := fmt.bprintf(string(age_buf[:]), "%d", s.age)
    age_buf[n] = 0
    rl.DrawText("Age:", lx, ly, UI_SMALL, COL_MUTED)
    rl.DrawText(cstring(raw_data(age_buf[:])), lx + 100, ly, UI_SMALL, COL_TEXT)
    ly += 28

    gender_opts := []cstring{"Male", "Female", "Nonbinary"}
    rl.DrawText("Gender:", lx, ly, UI_SMALL, COL_MUTED)
    rl.DrawText(gender_opts[s.gender_sel], lx + 100, ly, UI_SMALL, COL_TEXT)
    ly += 28

    pref_opts := []cstring{"Men", "Women", "Anyone", "Nobody"}
    rl.DrawText("Attracted to:", lx, ly, UI_SMALL, COL_MUTED)
    rl.DrawText(pref_opts[s.pref_sel], lx + 100, ly, UI_SMALL, COL_TEXT)
    ly += 28

    personality_opts := []cstring{
        "Ambitious Achiever", "Outgoing Merrymaker", "Outgoing Dynamo",
        "Laid-Back Guy", "Sweetie", "Cranky",
    }
    rl.DrawText("Personality:", lx, ly, UI_SMALL, COL_MUTED)
    rl.DrawText(personality_opts[s.personality_sel], lx + 100, ly, UI_SMALL, COL_TEXT)
    ly += 28

    pronoun_opts := []cstring{"he/him", "she/her", "they/them"}
    rl.DrawText("Pronouns:", lx, ly, UI_SMALL, COL_MUTED)
    rl.DrawText(pronoun_opts[s.pronouns_sel], lx + 100, ly, UI_SMALL, COL_TEXT)
    ly += 28

    spr_buf: [16]u8
    n2 := fmt.bprintf(string(spr_buf[:]), "Sprite %d", s.sprite_sel + 1)
    spr_buf[n2] = 0
    rl.DrawText("Sprite:", lx, ly, UI_SMALL, COL_MUTED)
    rl.DrawText(cstring(raw_data(spr_buf[:])), lx + 100, ly, UI_SMALL, COL_TEXT)

    // Buttons
    by := py + ph - 60
    yes_rect  := rl.Rectangle{f32(px + 20),       f32(by), 180, 40}
    back_rect := rl.Rectangle{f32(px + pw - 200), f32(by), 180, 40}

    hov_yes  := rl.CheckCollisionPointRec(rl.GetMousePosition(), yes_rect)
    hov_back := rl.CheckCollisionPointRec(rl.GetMousePosition(), back_rect)

    rl.DrawRectangleRec(yes_rect,  hov_yes  ? COL_CONFIRM : rl.Color{40, 120, 70, 255})
    rl.DrawRectangleRec(back_rect, hov_back ? COL_HOVER   : COL_INPUT)
    rl.DrawText("Looks good!",  px + 36, by + 10, UI_FSIZE, COL_TEXT)
    rl.DrawText("<- Go back",  px + pw - 186, by + 10, UI_FSIZE, COL_TEXT)

    if hov_back && rl.IsMouseButtonPressed(.LEFT) {
        s.show_confirm = false
        return false
    }

    if hov_yes && rl.IsMouseButtonPressed(.LEFT) {
        // Populate out
        out^ = {}
        name_str := input_field_str(&s.name_field)
        copy(out.name[:], []u8(name_str))
        nick_str := input_field_str(&s.nick_field)
        copy(out.nickname[:], []u8(nick_str))
        out.age         = s.age
        out.gender      = Gender(s.gender_sel)
        out.dating_pref = DatingPref(s.pref_sel)
        out.personality = Personality(s.personality_sel)
        out.pronouns    = Pronouns(s.pronouns_sel)
        out.sprite      = s.sprite_sel
        return true
    }

    return false
}

