package dmls

import rl "vendor:raylib"
import "core:fmt"
import "core:strings"
import "core:c"

// ---- Relationship query state ----------------------------------------------

MAX_REL_RESULTS :: 64

RelResult :: struct {
    other_id   : u32,
    other_name : string,
    tag        : string,
}

ResidentListScreen :: struct {
    selected_id : u32,
    rel_results : [MAX_REL_RESULTS]RelResult,
    rel_count   : int,
    scroll_y    : f32,
}

// Query Epilog for all relationships of `id`.
_query_relationships :: proc(
    s: ^ResidentListScreen,
    id: u32,
    res: ^Residents,
    engine: ^EpilogEngine,
) {
    s.rel_count = 0

    buf_id : [32]u8
    atom   := character_atom(id, buf_id[:])

    // Query: relationship(atom, Other, Tag)
    buf_goal: [128]u8
    n := fmt.bprintf(string(buf_goal[:]), "relationship(%s, Other, Tag)", atom)
    buf_goal[n] = 0

    Ctx :: struct {
        s   : ^ResidentListScreen,
        res : ^Residents,
    }
    ctx := Ctx{s, res}

    cb :: proc "c" (soln: ^EpilogSolution, ud: rawptr) -> EpilogSignal {
        ctx := cast(^Ctx)ud
        s   := ctx.s

        other_atom : cstring
        tag_atom   : cstring
        for i in 0..<epilog_soln_var_count(soln) {
            name := epilog_soln_var_name(soln, i)
            val  := epilog_soln_var_atom(soln, i)
            if name == nil || val == nil do continue
            switch string(name) {
            case "Other": other_atom = val
            case "Tag":   tag_atom   = val
            }
        }

        if other_atom != nil && tag_atom != nil && s.rel_count < MAX_REL_RESULTS {
            // Resolve other_atom to character id
            other_str := string(other_atom)
            other_id  := u32(0)
            if len(other_str) > 5 && other_str[:5] == "char_" {
                id_part := other_str[5:]
                for ch in id_part {
                    if ch >= '0' && ch <= '9' {
                        other_id = other_id * 10 + u32(ch - '0')
                    }
                }
            }

            idx := s.rel_count
            s.rel_results[idx].other_id   = other_id
            s.rel_results[idx].other_name = string(other_atom)
            s.rel_results[idx].tag        = string(tag_atom)

            // Try to replace atom with real name from residents
            if ctx.res != nil {
                c := residents_find(ctx.res, other_id)
                if c != nil {
                    s.rel_results[idx].other_name = character_name(c)
                }
            }
            s.rel_count += 1
        }
        return .EPILOG_NEXT
    }

    epilog_query(engine, cstring(raw_data(buf_goal[:])), cb, &ctx)
}

// Returns true when the player clicks "Add resident" to go to creation.
resident_list_update :: proc(
