/*
 * main.odin — DMLS entry point.
 *
 * Phase 1 (skeleton): initialises Epilog, runs the bridge smoke test,
 * then exits cleanly.  Raylib and the simulation loop are added in Phase 2+.
 */

package dmls

import "core:fmt"
import "core:c"
import "core:os"

/* ---- Bridge smoke-test state --------------------------------------------- */

BridgeSmokeCtx :: struct {
    found_bob:  bool,
    found_carol: bool,
    solution_count: int,
}

smoke_callback :: proc "c" (soln: ^EpilogSolution, userdata: rawptr) -> EpilogSignal {
    ctx := cast(^BridgeSmokeCtx)userdata

    n := epilog_soln_var_count(soln)
    for i in 0..<n {
        name := epilog_soln_var_name(soln, i)
        val  := epilog_soln_var_atom(soln, i)
        if name != nil && val != nil {
            if string(val) == "bob"   { ctx.found_bob   = true }
            if string(val) == "carol" { ctx.found_carol = true }
        }
    }
    ctx.solution_count += 1
    return .EPILOG_NEXT
}

/* ---- Bridge smoke test ---------------------------------------------------- */

run_bridge_smoke_test :: proc() -> bool {
    fmt.println("=== Bridge smoke test ===")
    fmt.printf("Epilog version: %s\n\n", epilog_version_string())

    e := epilog_create()
    if e == nil {
        fmt.eprintln("FAIL: epilog_create() returned nil")
        return false
    }
    defer epilog_destroy(e)

    /* Assert facts */
    epilog_load_string(e, "parent(alice, bob).")
    epilog_load_string(e, "parent(bob, carol).")
    epilog_load_string(e, "grandparent(X, Y) :- parent(X, Z), parent(Z, Y).")

    /* Query 1: ground fact lookup */
    n1 := epilog_query(e, "parent(alice, bob)", nil, nil)
    fmt.printf("parent(alice, bob): %d solution(s)\n", n1)
    if n1 != 1 {
        fmt.eprintln("FAIL: expected 1 solution for ground fact")
        return false
    }

    /* Query 2: variable binding */
    ctx: BridgeSmokeCtx
    n2 := epilog_query(e, "grandparent(alice, X)", smoke_callback, &ctx)
    fmt.printf("grandparent(alice, X): %d solution(s)\n", n2)
    for i in 0..<n2 {
        _ = i
    }

    if n2 != 1 || !ctx.found_carol {
        fmt.eprintln("FAIL: grandparent(alice, X) should bind X=carol")
        return false
    }

    /* Query 3: should fail */
    n3 := epilog_query(e, "parent(carol, _)", nil, nil)
    fmt.printf("parent(carol, _): %d solution(s) [expect 0]\n", n3)
    if n3 != 0 {
        fmt.eprintln("FAIL: expected 0 solutions")
        return false
    }

    /* Query 4: variable bindings inspection */
    ctx2: BridgeSmokeCtx
    _ = epilog_query(e, "parent(X, Y)", smoke_callback, &ctx2)
    fmt.printf("parent(X, Y): %d solution(s) [expect 2]\n", ctx2.solution_count)
    if ctx2.solution_count != 2 {
        fmt.eprintln("FAIL: expected 2 solutions for parent(X, Y)")
        return false
    }

    fmt.println("\n=== Bridge smoke test: PASS ===")
    return true
}

/* ---- Main ----------------------------------------------------------------- */

main :: proc() {
    fmt.println("DMLS — Deb's Minimal Life Simulator")
    fmt.println("Phase 1: Project skeleton")
    fmt.println()

    if !run_bridge_smoke_test() {
        fmt.eprintln("Bridge smoke test failed — aborting.")
        os.exit(1)
    }

    fmt.println()
    fmt.println("M1 complete. Raylib window and simulation loop come in Phase 2.")
}

