package dmls

import rl "vendor:raylib"
import "core:fmt"
import "core:strings"

// ---- Relationship query state ----------------------------------------------

MAX_REL_RESULTS :: 64

RelResult :: struct {
    other_id   : u32,
    other_name : string,
    tag        : string,
}

ResidentListScreen :: struct {
    selected_id : u32,
    rel_results : [MAX_REL_RESULTS]RelResult,
    rel_count   : int,
}

// Raw callback data (no context available in "c" procs)
RelQueryAccum :: struct {
    results : ^[MAX_REL_RESULTS]RelResult,
    count   : ^int,
}

_rel_query_cb :: proc "c" (soln: ^EpilogSolution, ud: rawptr) -> EpilogSignal {
    acc := cast(^RelQueryAccum)ud

    other_atom: cstring
    tag_atom  : cstring

    for i in 0..<epilog_soln_var_count(soln) {
        name := epilog_soln_var_name(soln, i)
        val  := epilog_soln_var_atom(soln, i)
        if name == nil || val == nil do continue
        switch string(name) {
        case "Other": other_atom = val
        case "Tag":   tag_atom   = val
        }
    }

    if other_atom != nil && tag_atom != nil && acc.count^ < MAX_REL_RESULTS {
        other_str := string(other_atom)
        other_id  := u32(0)
        if len(other_str) > 5 && other_str[:5] == "char_" {
            for ch in other_str[5:] {
                if ch >= '0' && ch <= '9' {
                    other_id = other_id * 10 + u32(ch - '0')
                }
            }
        }
        idx := acc.count^
        acc.results[idx].other_id   = other_id
        acc.results[idx].other_name = string(other_atom)
        acc.results[idx].tag        = string(tag_atom)
        acc.count^ += 1
    }
    return .EPILOG_NEXT
}

_query_relationships :: proc(
    s      : ^ResidentListScreen,
    id     : u32,
    res    : ^Residents,
    engine : ^EpilogEngine,
) {
    s.rel_count = 0

    buf_id  : [32]u8
    atom    := character_atom(id, buf_id[:])
    buf_goal: [128]u8
    gs := fmt.bprintf(buf_goal[:], "relationship(%s, Other, Tag)", atom)
    buf_goal[len(gs)] = 0

    acc := RelQueryAccum{&s.rel_results, &s.rel_count}
    epilog_query(engine, cstring(raw_data(buf_goal[:])), _rel_query_cb, &acc)

    // Resolve atom names to real character names (needs context, so done here)
    for i in 0..<s.rel_count {
        c := residents_find(res, s.rel_results[i].other_id)
        if c != nil {
            s.rel_results[i].other_name = character_name(c)
        }
    }
}

// Returns true when the player clicks "Add resident".
resident_list_update :: proc(
    s     : ^ResidentListScreen,
    res   : ^Residents,
    engine: ^EpilogEngine,
) -> bool {
    rl.ClearBackground(COL_BG)

    rl.DrawText("Island Residents", UI_LPAD, UI_PAD, UI_HSIZE, COL_TEXT)

    count_buf: [32]u8
    cs := fmt.bprintf(count_buf[:], "%d resident(s)", res.count)
    count_buf[len(cs)] = 0
    rl.DrawText(cstring(raw_data(count_buf[:])), UI_LPAD, UI_PAD + UI_HSIZE + 6, UI_SMALL, COL_MUTED)

    add_rect := rl.Rectangle{f32(SCREEN_W - 200), f32(UI_PAD), 180, 36}
    hov_add  := rl.CheckCollisionPointRec(rl.GetMousePosition(), add_rect)
    rl.DrawRectangleRec(add_rect, hov_add ? COL_ACCENT : COL_SELECT)
    rl.DrawText("+ Add resident", SCREEN_W - 190, UI_PAD + 8, UI_SMALL, COL_TEXT)
    if hov_add && rl.IsMouseButtonPressed(.LEFT) {
        return true
    }

    list_y := i32(UI_PAD + UI_HSIZE + 40)

    for i in 0..<res.count {
        c    := &res.chars[i]
        row  := rl.Rectangle{f32(UI_LPAD), f32(list_y + i32(i) * 48), 340, 42}
        sel  := c.id == s.selected_id
        hov  := rl.CheckCollisionPointRec(rl.GetMousePosition(), row)
        bg   := sel ? COL_SELECT : (hov ? COL_HOVER : COL_PANEL)
        rl.DrawRectangleRec(row, bg)
        rl.DrawRectangleLinesEx(row, 1, sel ? COL_ACCENT : COL_MUTED)

        hue := f32(c.sprite) / f32(SPRITE_COUNT)
        r   := u8(80 + 100 * (1 - hue))
        g   := u8(80 + 100 * hue)
        b   := u8(180 - 80 * hue)
        rl.DrawRectangle(i32(row.x) + 6, i32(row.y) + 9, 24, 24, rl.Color{r, g, b, 200})

        name_cstr := strings.clone_to_cstring(character_name(c), context.temp_allocator)
        rl.DrawText(name_cstr, i32(row.x) + 38, i32(row.y) + 6, UI_FSIZE, COL_TEXT)

        pers_cstr := strings.clone_to_cstring(personality_label(c.personality), context.temp_allocator)
        rl.DrawText(pers_cstr, i32(row.x) + 38, i32(row.y) + 26, UI_SMALL, COL_MUTED)

        if hov && rl.IsMouseButtonPressed(.LEFT) && c.id != s.selected_id {
            s.selected_id = c.id
            _query_relationships(s, c.id, res, engine)
        }
    }

    if res.count == 0 {
        rl.DrawText("No residents yet. Add the first one!", UI_LPAD + 8, list_y + 14, UI_FSIZE, COL_MUTED)
    }

    // Right panel — relationship detail
    if s.selected_id != 0 {
        rx := i32(UI_LPAD + 360)
        rl.DrawRectangle(rx - 10, list_y - 8, SCREEN_W - rx, SCREEN_H - list_y, COL_PANEL)

        sel_char := residents_find(res, s.selected_id)
        if sel_char != nil {
            name_cstr := strings.clone_to_cstring(character_name(sel_char), context.temp_allocator)
            rl.DrawText(name_cstr, rx, list_y, UI_HSIZE, COL_TEXT)

            ry := list_y + UI_HSIZE + 10

            pron_cstr := strings.clone_to_cstring(pronouns_label(sel_char.pronouns), context.temp_allocator)
            rl.DrawText(pron_cstr, rx, ry, UI_SMALL, COL_MUTED)
            ry += 22

            pers_cstr := strings.clone_to_cstring(personality_label(sel_char.personality), context.temp_allocator)
            rl.DrawText(pers_cstr, rx, ry, UI_SMALL, COL_MUTED)
            ry += 22

            age_buf: [32]u8
            age_s := fmt.bprintf(age_buf[:], "Age %d", sel_char.age)
            age_buf[len(age_s)] = 0
            rl.DrawText(cstring(raw_data(age_buf[:])), rx, ry, UI_SMALL, COL_MUTED)
            ry += 30

            rl.DrawText("Relationships:", rx, ry, UI_SMALL, COL_TEXT)
            ry += 22

            if s.rel_count == 0 {
                rl.DrawText("none", rx + 8, ry, UI_SMALL, COL_MUTED)
            } else {
                for ri in 0..<s.rel_count {
                    r := &s.rel_results[ri]
                    row_buf: [128]u8
                    nr := fmt.bprintf(row_buf[:], "%s  --  %s", r.other_name, r.tag)
                    row_buf[len(nr)] = 0
                    rl.DrawText(cstring(raw_data(row_buf[:])), rx + 8, ry, UI_SMALL, COL_TEXT)
                    ry += 22
                }
            }
        }
    }

    return false
}

/*
 * world.odin — World seed system and character placement / wandering (M3).
 */

package dmls

import "core:fmt"

// ---- World -----------------------------------------------------------------

World :: struct {
    seed        : u64,
    grid        : Grid,
    rng         : u64,              // LCG state for placement/wandering
    tick        : u64,
    // Per-character position cache (mirrors grid occupant)
    positions   : [MAX_RESIDENTS][2]i32,    // [id-1] = {col, row}
}

world_init :: proc(w: ^World, seed: u64) {
    w.seed = seed
    w.rng  = seed
    w.tick = 0
    grid_generate(&w.grid, seed)
}

// Spawn a newly created character onto the grid.
world_spawn_character :: proc(w: ^World, res: ^Residents, id: u32) -> bool {
    c := residents_find(res, id)
    if c == nil do return false

    col, row, ok := grid_find_spawn(&w.grid, &w.rng)
    if !ok do return false

    if !grid_place_character(&w.grid, id, col, row) do return false

    c.position = {col, row}
    idx := id - 1
    if int(idx) < MAX_RESIDENTS {
        w.positions[idx] = {col, row}
    }
    return true
}

// One wander step per character — moves to a random adjacent walkable cell.
world_tick_wander :: proc(w: ^World, res: ^Residents) {
    dx := [4]i32{0, 0, 1, -1}
    dy := [4]i32{1, -1, 0, 0}

    for i in 0..<res.count {
        c   := &res.chars[i]
        col := c.position[0]
        row := c.position[1]

        // Pick a random direction
        w.rng = w.rng * 6364136223846793005 + 1442695040888963407
        dir  := int((w.rng >> 33) % 4)

        nc := col + dx[dir]
        nr := row + dy[dir]

        if grid_move_character(&w.grid, c.id, col, row, nc, nr) {
            c.position = {nc, nr}
            idx := c.id - 1
            if int(idx) < MAX_RESIDENTS {
                w.positions[idx] = {nc, nr}
            }
        }
    }
    w.tick += 1
}

// Format the seed as a hex string for display.
world_seed_string :: proc(w: ^World, buf: []u8) -> cstring {
    s := fmt.bprintf(buf, "%016X", w.seed)
    buf[len(s)] = 0
    return cstring(raw_data(buf))
}

package dmls

import "core:fmt"
import "core:strings"
import "core:c"

// ---- Enumerations ----------------------------------------------------------

Gender :: enum u8 {
    Male,
    Female,
    Nonbinary,
}

DatingPref :: enum u8 {
    Male,
    Female,
    Any,
    None,
}

Pronouns :: enum u8 {
    He_Him,
    She_Her,
    They_Them,
}

Personality :: enum u8 {
    Ambitious_Achiever,
    Outgoing_Merrymaker,
    Outgoing_Dynamo,
    Laid_Back_Guy,
    Sweetie,
    Cranky,
}

RelationshipTag :: enum u8 {
    Stranger,
    Acquaintance,
    Friend,
    Sibling,
    Partner,
}

// ---- Character struct ------------------------------------------------------

MAX_NAME_LEN  :: 32
MAX_RESIDENTS :: 64

Character :: struct {
    id          : u32,
    name        : [MAX_NAME_LEN]u8,
    nickname    : [MAX_NAME_LEN]u8,
    age         : u8,
    gender      : Gender,
    dating_pref : DatingPref,
    personality : Personality,
    pronouns    : Pronouns,
    position    : [2]i32,
    sprite      : u32,
}

character_name :: proc(c: ^Character) -> string {
    return strings.truncate_to_byte(string(c.name[:]), 0)
}

character_nickname :: proc(c: ^Character) -> string {
    return strings.truncate_to_byte(string(c.nickname[:]), 0)
}

character_atom :: proc(id: u32, buf: []u8) -> cstring {
    s := fmt.bprintf(buf, "char_%d", id)
    buf[len(s)] = 0
    return cstring(raw_data(buf))
}

// ---- Resident registry -----------------------------------------------------

Residents :: struct {
    chars  : [MAX_RESIDENTS]Character,
    count  : u32,
    next_id: u32,
    rel    : [MAX_RESIDENTS][MAX_RESIDENTS]RelationshipTag,
}

residents_init :: proc(r: ^Residents) {
    r^ = {}
    r.next_id = 1
}

residents_add :: proc(r: ^Residents, c: Character) -> u32 {
    assert(r.count < MAX_RESIDENTS)
    idx := r.count
    r.chars[idx] = c
    r.chars[idx].id = r.next_id
    r.next_id += 1
    r.count += 1
    return r.chars[idx].id
}

residents_find :: proc(r: ^Residents, id: u32) -> ^Character {
    for i in 0..<r.count {
        if r.chars[i].id == id do return &r.chars[i]
    }
    return nil
}

// ---- Display helpers -------------------------------------------------------

gender_label :: proc(g: Gender) -> string {
    switch g {
    case .Male:      return "Male"
    case .Female:    return "Female"
    case .Nonbinary: return "Nonbinary"
    }
    return ""
}

dating_pref_label :: proc(d: DatingPref) -> string {
    switch d {
    case .Male:   return "Men"
    case .Female: return "Women"
    case .Any:    return "Anyone"
    case .None:   return "Nobody"
    }
    return ""
}

pronouns_label :: proc(p: Pronouns) -> string {
    switch p {
    case .He_Him:    return "he/him"
    case .She_Her:   return "she/her"
    case .They_Them: return "they/them"
    }
    return ""
}

personality_label :: proc(p: Personality) -> string {
    switch p {
    case .Ambitious_Achiever:  return "Ambitious Achiever"
    case .Outgoing_Merrymaker: return "Outgoing Merrymaker"
    case .Outgoing_Dynamo:     return "Outgoing Dynamo"
    case .Laid_Back_Guy:       return "Laid-Back Guy"
    case .Sweetie:             return "Sweetie"
    case .Cranky:              return "Cranky"
    }
    return ""
}

personality_atom :: proc(p: Personality) -> cstring {
    switch p {
    case .Ambitious_Achiever:  return "ambitious_achiever"
    case .Outgoing_Merrymaker: return "outgoing_merrymaker"
    case .Outgoing_Dynamo:     return "outgoing_dynamo"
    case .Laid_Back_Guy:       return "laid_back_guy"
    case .Sweetie:             return "sweetie"
    case .Cranky:              return "cranky"
    }
    return "unknown"
}

dating_pref_atom :: proc(d: DatingPref) -> cstring {
    switch d {
    case .Male:   return "male"
    case .Female: return "female"
    case .Any:    return "any"
    case .None:   return "none"
    }
    return "none"
}

relationship_atom :: proc(t: RelationshipTag) -> cstring {
    switch t {
    case .Stranger:     return "stranger"
    case .Acquaintance: return "acquaintance"
    case .Friend:       return "friend"
    case .Sibling:      return "sibling"
    case .Partner:      return "partner"
    }
    return "stranger"
}

// ---- Assert character into Epilog ------------------------------------------

epilog_assert_character :: proc(engine: ^EpilogEngine, c: ^Character) {
    buf_id : [32]u8
    buf_src: [256]u8

    atom := character_atom(c.id, buf_id[:])

    gender_str: cstring
    switch c.gender {
    case .Male:      gender_str = "male"
    case .Female:    gender_str = "female"
    case .Nonbinary: gender_str = "nonbinary"
    }

    s := fmt.bprintf(buf_src[:], "character(%s, %s).", atom, personality_atom(c.personality))
    buf_src[len(s)] = 0
    epilog_load_string(engine, cstring(raw_data(buf_src[:])))

    s = fmt.bprintf(buf_src[:], "dating_pref(%s, %s).", atom, dating_pref_atom(c.dating_pref))
    buf_src[len(s)] = 0
    epilog_load_string(engine, cstring(raw_data(buf_src[:])))

    s = fmt.bprintf(buf_src[:], "gender(%s, %s).", atom, gender_str)
    buf_src[len(s)] = 0
    epilog_load_string(engine, cstring(raw_data(buf_src[:])))
}

epilog_assert_relationship :: proc(engine: ^EpilogEngine, id_a, id_b: u32, tag: RelationshipTag) {
    buf_a  : [32]u8
    buf_b  : [32]u8
    buf_src: [128]u8

    atom_a := character_atom(id_a, buf_a[:])
    atom_b := character_atom(id_b, buf_b[:])

    s := fmt.bprintf(buf_src[:], "relationship(%s, %s, %s).", atom_a, atom_b, relationship_atom(tag))
    buf_src[len(s)] = 0
    epilog_load_string(engine, cstring(raw_data(buf_src[:])))
}

/*
 * main.odin — DMLS entry point (M2 + M3).
 *
 * Screen state machine:
 *   .World_Setup   — enter seed, then generate
 *   .Residents     — resident list + "Add resident" button
 *   .Creation      — character creation form
 *   .Rel_Seeding   — tag relationships for the new character
 *   .Simulation    — dual-panel: grid view + stats panel
 */

package dmls

import rl  "vendor:raylib"
import "core:fmt"
import "core:strings"

// ---- Screen enum -----------------------------------------------------------

AppScreen :: enum {
    World_Setup,
    Residents,
    Creation,
    Rel_Seeding,
    Simulation,
}

// ---- App state -------------------------------------------------------------

App :: struct {
    screen        : AppScreen,

    // Epilog engine
    engine        : ^EpilogEngine,

    // Simulation data
    world         : World,
    residents     : Residents,

    // UI state
    creation      : CreationScreen,
    rel_seeding   : RelSeeding,
    resident_list : ResidentListScreen,

    // Pending character (between creation confirm and rel seeding)
    pending_char  : Character,
    pending_id    : u32,

    // Camera (grid centre cell)
    cam_col       : i32,
    cam_row       : i32,

    // Seed entry
    seed_field    : InputField,
    seed_err      : bool,

    // Stats panel timer
    stats_timer   : f32,
}

// ---- Helpers ---------------------------------------------------------------

_parse_seed :: proc(s: string) -> (u64, bool) {
    val := u64(0)
    if len(s) == 0 do return 0, false
    for ch in s {
        switch ch {
        case '0'..='9': val = val * 16 + u64(ch - '0')
        case 'a'..='f': val = val * 16 + u64(ch - 'a' + 10)
        case 'A'..='F': val = val * 16 + u64(ch - 'A' + 10)
        case: return 0, false
        }
    }
    return val, true
}

_default_seed :: proc() -> u64 {
    // Mix timestamp-ish constant for a fun default
    return 0x596767647261736C  // "Yggdrasl" in hex
}

// ---- World setup screen ----------------------------------------------------

_draw_world_setup :: proc(app: ^App) -> bool {
    rl.ClearBackground(COL_BG)
    rl.DrawText("DMLS", UI_LPAD, UI_PAD, 48, COL_TEXT)
    rl.DrawText("Deb's Minimal Life Simulator", UI_LPAD, UI_PAD + 54, UI_SMALL, COL_MUTED)

    y := i32(UI_PAD + 110)
    rl.DrawText("World seed (hex)", UI_LPAD, y, UI_SMALL, COL_MUTED)
    y += 22

    input_field_draw(&app.seed_field, UI_LPAD, y, 340, 38, "")
    if rl.CheckCollisionPointRec(rl.GetMousePosition(),
            rl.Rectangle{f32(UI_LPAD), f32(y), 340, 38}) &&
            rl.IsMouseButtonPressed(.LEFT) {
        app.seed_field.active = true
    }
    input_field_update(&app.seed_field)

    if app.seed_err {
        rl.DrawText("Invalid hex seed", UI_LPAD, y + 44, UI_SMALL, rl.RED)
    }

    y += 54
    rnd_rect := rl.Rectangle{f32(UI_LPAD + 350), f32(y - 54), 160, 38}
    hov_rnd  := rl.CheckCollisionPointRec(rl.GetMousePosition(), rnd_rect)
    rl.DrawRectangleRec(rnd_rect, hov_rnd ? COL_HOVER : COL_INPUT)
    rl.DrawRectangleLinesEx(rnd_rect, 1, COL_MUTED)
    rl.DrawText("Random seed", UI_LPAD + 360, y - 44, UI_SMALL, COL_MUTED)
    if hov_rnd && rl.IsMouseButtonPressed(.LEFT) {
        // XOR shift from frame counter
        rng := u64(rl.GetTime() * 1e9)
        rng ~= rng << 13; rng ~= rng >> 7; rng ~= rng << 17
        buf: [20]u8
        ns := fmt.bprintf(buf[:], "%016X", rng)
        app.seed_field.len = 0
        for i in 0..<len(ns) { app.seed_field.buf[i] = buf[i] }
        app.seed_field.len = len(ns)
    }

    go_rect := rl.Rectangle{f32(UI_LPAD), f32(y), 200, 42}
    hov_go  := rl.CheckCollisionPointRec(rl.GetMousePosition(), go_rect)
    rl.DrawRectangleRec(go_rect, hov_go ? COL_ACCENT : COL_SELECT)
    rl.DrawText("Generate island ->", UI_LPAD + 12, y + 11, UI_FSIZE, COL_TEXT)

    if (hov_go && rl.IsMouseButtonPressed(.LEFT)) || rl.IsKeyPressed(.ENTER) {
        seed_str := input_field_str(&app.seed_field)
        seed     := u64(0)
        ok       := false
        if len(seed_str) == 0 {
            seed, ok = _default_seed(), true
        } else {
            seed, ok = _parse_seed(seed_str)
        }
        if !ok {
            app.seed_err = true
            return false
        }
        app.seed_err = false
        world_init(&app.world, seed)
        return true
    }
    return false
}

// ---- Stats panel (right side of simulation) --------------------------------

STATS_X :: SCREEN_W * 55 / 100
SIM_W   :: STATS_X
SIM_H   :: SCREEN_H

_draw_stats_panel :: proc(app: ^App) {
    rx := i32(STATS_X)
    rl.DrawRectangle(rx, 0, i32(SCREEN_W) - rx, i32(SCREEN_H), COL_PANEL)
    rl.DrawLine(rx, 0, rx, i32(SCREEN_H), COL_MUTED)

    y := i32(UI_PAD)

    // Seed
    rl.DrawText("ISLAND STATS", rx + UI_PAD, y, UI_SMALL, COL_ACCENT)
    y += 24

    seed_buf: [24]u8
    rl.DrawText("Seed:", rx + UI_PAD, y, UI_SMALL, COL_MUTED)
    seed_cstr := world_seed_string(&app.world, seed_buf[:])
    rl.DrawText(seed_cstr, rx + UI_PAD + 50, y, UI_SMALL, COL_TEXT)
    y += 20

    // Tick
    tick_buf: [32]u8
    ts := fmt.bprintf(tick_buf[:], "Tick: %d", app.world.tick)
    tick_buf[len(ts)] = 0
    rl.DrawText(cstring(raw_data(tick_buf[:])), rx + UI_PAD, y, UI_SMALL, COL_TEXT)
    y += 20

    // Resident count
    cnt_buf: [32]u8
    cs := fmt.bprintf(cnt_buf[:], "Residents: %d", app.residents.count)
    cnt_buf[len(cs)] = 0
    rl.DrawText(cstring(raw_data(cnt_buf[:])), rx + UI_PAD, y, UI_SMALL, COL_TEXT)
    y += 28

    rl.DrawLine(rx + i32(UI_PAD), y, i32(SCREEN_W - UI_PAD), y, COL_MUTED)
    y += 10

    // Residents list
    rl.DrawText("RESIDENTS", rx + UI_PAD, y, UI_SMALL, COL_ACCENT)
    y += 20

    for i in 0..<app.residents.count {
        c := &app.residents.chars[i]
        // Colour dot
        hue := f32(c.sprite) / f32(SPRITE_COUNT)
        r   := u8(80 + 100 * (1 - hue))
        g   := u8(80 + 100 * hue)
        b   := u8(180 - 80 * hue)
        rl.DrawRectangle(rx + UI_PAD, y + 2, 10, 10, rl.Color{r, g, b, 200})

        name_cstr := strings.clone_to_cstring(character_name(c), context.temp_allocator)
        rl.DrawText(name_cstr, rx + UI_PAD + 16, y, UI_SMALL, COL_TEXT)
        y += 18
    }
    if app.residents.count == 0 {
        rl.DrawText("none yet", rx + UI_PAD, y, UI_SMALL, COL_MUTED)
        y += 18
    }
    y += 8

    rl.DrawLine(rx + i32(UI_PAD), y, i32(SCREEN_W - UI_PAD), y, COL_MUTED)
    y += 10

    // Nav buttons
    rl.DrawText("NAVIGATE", rx + UI_PAD, y, UI_SMALL, COL_ACCENT)
    y += 20

    res_rect := rl.Rectangle{f32(rx + UI_PAD), f32(y), 160, 30}
    hov_res  := rl.CheckCollisionPointRec(rl.GetMousePosition(), res_rect)
    rl.DrawRectangleRec(res_rect, hov_res ? COL_HOVER : COL_INPUT)
    rl.DrawText("Residents ->", rx + UI_PAD + 8, y + 7, UI_SMALL, COL_TEXT)
    if hov_res && rl.IsMouseButtonPressed(.LEFT) {
        app.screen = .Residents
        app.resident_list = {}
    }
}

// ---- Simulation screen -----------------------------------------------------

_update_simulation :: proc(app: ^App) {
    // WASD camera pan
    if rl.IsKeyDown(.W) { app.cam_row -= 2 }
    if rl.IsKeyDown(.S) { app.cam_row += 2 }
    if rl.IsKeyDown(.A) { app.cam_col -= 2 }
    if rl.IsKeyDown(.D) { app.cam_col += 2 }
    app.cam_col = clamp(app.cam_col, 0, GRID_W - 1)
    app.cam_row = clamp(app.cam_row, 0, GRID_H - 1)

    // Tick wander at ~1 Hz
    app.stats_timer += rl.GetFrameTime()
    if app.stats_timer >= 1.0 {
        app.stats_timer = 0
        world_tick_wander(&app.world, &app.residents)
    }

    rl.ClearBackground(COL_BG)

    // Grid view on the left
    grid_render(&app.world.grid, 0, 0, SIM_W, SIM_H, app.cam_col, app.cam_row)

    // WASD hint
    rl.DrawText("WASD: pan camera", 8, SCREEN_H - 20, UI_SMALL, COL_MUTED)

    // Stats panel on the right
    _draw_stats_panel(app)
}

// ---- Main ------------------------------------------------------------------

main :: proc() {
    rl.SetConfigFlags({.WINDOW_RESIZABLE})
    rl.InitWindow(SCREEN_W, SCREEN_H, "DMLS — Deb's Minimal Life Simulator")
    rl.SetTargetFPS(60)
    defer rl.CloseWindow()

    app := new(App)
    defer free(app)
    app.engine = epilog_create()
    defer epilog_destroy(app.engine)

    residents_init(&app.residents)
    app.screen  = .World_Setup
    app.cam_col = GRID_W / 2
    app.cam_row = GRID_H / 2

    // Seed entry: show default seed
    {
        def := _default_seed()
        ds  := fmt.bprintf(app.seed_field.buf[:], "%016X", def)
        app.seed_field.len = len(ds)
        app.seed_field.active = true
    }

    // Load Epilog rules used throughout the simulation
    epilog_load_string(app.engine,
        "rivals(X, Y) :- crushing(X, Z), crushing(Y, Z), X \\= Y.")
    epilog_load_string(app.engine,
        "eligible(X, Y) :- dating_pref(X, Pref), gender(Y, Pref), X \\= Y.")
    epilog_load_string(app.engine,
        "best_friends(X, Y) :- relationship(X, Y, friend), relationship(Y, X, friend).")

    for !rl.WindowShouldClose() {
        rl.BeginDrawing()
        free_all(context.temp_allocator)

        switch app.screen {

        case .World_Setup:
            if _draw_world_setup(app) {
                app.screen  = .Residents
                app.cam_col = GRID_W / 2
                app.cam_row = GRID_H / 2
            }

        case .Residents:
            if resident_list_update(&app.resident_list, &app.residents, app.engine) {
                creation_screen_init(&app.creation)
                app.screen = .Creation
            }
            // "Simulate" button when ≥1 resident exists
            sim_rect := rl.Rectangle{f32(SCREEN_W - 200), f32(SCREEN_H - 60), 180, 42}
            hov_sim  := rl.CheckCollisionPointRec(rl.GetMousePosition(), sim_rect)
            if app.residents.count > 0 {
                rl.DrawRectangleRec(sim_rect, hov_sim ? COL_ACCENT2 : COL_ACCENT)
                rl.DrawText("Simulate ->", SCREEN_W - 188, SCREEN_H - 46, UI_FSIZE, COL_TEXT)
                if hov_sim && rl.IsMouseButtonPressed(.LEFT) {
                    app.screen = .Simulation
                }
            }

        case .Creation:
            new_char: Character
            if creation_screen_update(&app.creation, &new_char) {
                // Add to residents, assert into Epilog, then go to rel seeding
                app.pending_char = new_char
                app.pending_id   = residents_add(&app.residents, new_char)
                epilog_assert_character(app.engine, residents_find(&app.residents, app.pending_id))
                world_spawn_character(&app.world, &app.residents, app.pending_id)
                rel_seeding_init(&app.rel_seeding, app.pending_id, &app.residents)
                app.screen = .Rel_Seeding
            }
            // Back button
            back_rect := rl.Rectangle{f32(SCREEN_W - 130), f32(SCREEN_H - 50), 120, 36}
            hov_back  := rl.CheckCollisionPointRec(rl.GetMousePosition(), back_rect)
            rl.DrawRectangleRec(back_rect, hov_back ? COL_HOVER : COL_INPUT)
            rl.DrawText("<- Back", SCREEN_W - 122, SCREEN_H - 40, UI_SMALL, COL_MUTED)
            if hov_back && rl.IsMouseButtonPressed(.LEFT) {
                app.screen = .Residents
            }

        case .Rel_Seeding:
            if rel_seeding_update(&app.rel_seeding, &app.residents) {
                rel_seeding_commit(&app.rel_seeding, &app.residents, app.engine)
                app.screen = .Residents
                app.resident_list = {}
            }

        case .Simulation:
            _update_simulation(&app)
        }

        rl.EndDrawing()
    }
}

/*
 * grid.odin — 256×256 world grid (M3).
 *
 * Each cell stores a terrain type, occupant character id (0 = empty),
 * and a generic object id (0 = none).
 *
 * Terrain zones and their walkability:
 *   .Water  — impassable
 *   .Beach  — walkable, spawnable
 *   .Grass  — walkable, spawnable
 *   .Town   — walkable, spawnable (preferred spawn)
 *   .Forest — walkable, not spawnable
 */

package dmls

import rl "vendor:raylib"
import "core:math"

GRID_W :: 256
GRID_H :: 256

// Terrain scale: smaller = more zoomed-out noise features.
TERRAIN_SCALE :: 0.035
TERRAIN_OCTAVES :: 5

Terrain :: enum u8 {
    Water,
    Beach,
    Grass,
    Town,
    Forest,
}

Cell :: struct {
    terrain   : Terrain,
    occupant  : u32,    // character id, 0 = empty
    object_id : u32,    // reserved for Phase 8 objects
}

Grid :: struct {
    cells     : [GRID_H][GRID_W]Cell,
    world_seed: u64,
}

// ---- Terrain colour lookup -------------------------------------------------

terrain_color :: proc(t: Terrain) -> rl.Color {
    switch t {
    case .Water:  return rl.Color{30,  80,  160, 255}
    case .Beach:  return rl.Color{210, 190, 130, 255}
    case .Grass:  return rl.Color{60,  140, 60,  255}
    case .Town:   return rl.Color{160, 140, 110, 255}
    case .Forest: return rl.Color{30,  90,  30,  255}
    }
    return rl.Color{0, 0, 0, 255}
}

terrain_walkable :: proc(t: Terrain) -> bool {
    return t != .Water
}

terrain_spawnable :: proc(t: Terrain) -> bool {
    return t == .Grass || t == .Town || t == .Beach
}

// ---- Grid generation -------------------------------------------------------

grid_generate :: proc(g: ^Grid, seed: u64) {
    g.world_seed = seed
    g^ = {}
    g.world_seed = seed

    ns: NoiseState
    noise_init(&ns, seed)

    // Second noise for town/forest layer
    ns2: NoiseState
    noise_init(&ns2, seed ~ 0xdeadbeefcafe1234)

    for row in 0..<GRID_H {
        for col in 0..<GRID_W {
            x := f64(col)
            y := f64(row)

            // Island mask: distance from centre falls off to water at edges
            cx  := f64(GRID_W) / 2.0
            cy  := f64(GRID_H) / 2.0
            dx  := (x - cx) / cx
            dy  := (y - cy) / cy
            dist := math.sqrt(dx*dx + dy*dy)

            // Base elevation from fBm noise
            elevation := fbm(&ns, x * TERRAIN_SCALE, y * TERRAIN_SCALE, TERRAIN_OCTAVES)
            // Clamp to [-1,1] roughly — fBm with 5 octaves goes beyond 1
            elevation = elevation * 0.5

            // Apply island radial mask — edges become water
            elevation -= dist * 1.2

            // Secondary noise for town/forest differentiation
            detail := perlin2(&ns2, x * TERRAIN_SCALE * 2, y * TERRAIN_SCALE * 2)

            terrain: Terrain
            switch {
            case elevation < -0.3:
                terrain = .Water
            case elevation < -0.1:
                terrain = .Beach
            case elevation < 0.25:
                // Grass vs town vs forest based on detail noise
                if detail > 0.3 {
                    terrain = .Town
                } else if detail < -0.3 {
                    terrain = .Forest
                } else {
                    terrain = .Grass
                }
            case:
                terrain = .Forest   // high ground = dense forest
            }

            g.cells[row][col].terrain = terrain
        }
    }
}

// ---- Occupant helpers ------------------------------------------------------

grid_place_character :: proc(g: ^Grid, id: u32, col, row: i32) -> bool {
    if col < 0 || col >= GRID_W || row < 0 || row >= GRID_H do return false
    cell := &g.cells[row][col]
    if cell.occupant != 0 do return false
    if !terrain_walkable(cell.terrain) do return false
    cell.occupant = id
    return true
}

grid_move_character :: proc(g: ^Grid, id: u32, old_col, old_row, new_col, new_row: i32) -> bool {
    if new_col < 0 || new_col >= GRID_W || new_row < 0 || new_row >= GRID_H do return false
    dst := &g.cells[new_row][new_col]
    if dst.occupant != 0 do return false
    if !terrain_walkable(dst.terrain) do return false
    g.cells[old_row][old_col].occupant = 0
    dst.occupant = id
    return true
}

grid_remove_character :: proc(g: ^Grid, col, row: i32) {
    if col >= 0 && col < GRID_W && row >= 0 && row < GRID_H {
        g.cells[row][col].occupant = 0
    }
}

// ---- Spawn: find a random spawnable cell using a simple LCG ----------------

grid_find_spawn :: proc(g: ^Grid, rng: ^u64) -> (col, row: i32, ok: bool) {
    for _ in 0..<512 {
        rng^ = rng^ * 6364136223846793005 + 1442695040888963407
        c := i32((rng^ >> 33) % GRID_W)
        r := i32((rng^ >> 17) % GRID_H)
        cell := &g.cells[r][c]
        if terrain_spawnable(cell.terrain) && cell.occupant == 0 {
            return c, r, true
        }
    }
    return 0, 0, false
}

// ---- Rendering -------------------------------------------------------------

// cell_px — pixel size when rendering at the given zoom.
RENDER_CELL_PX :: 3   // each grid cell = 3×3 pixels

// Render the grid into the current drawing context.
// origin_x/y: top-left pixel of the simulation view.
// view_w/h:   pixel size of the simulation panel.
grid_render :: proc(g: ^Grid, origin_x, origin_y, view_w, view_h: i32,
                    cam_col, cam_row: i32) {
    visible_cols := view_w  / RENDER_CELL_PX + 2
    visible_rows := view_h / RENDER_CELL_PX + 2

    start_col := cam_col - visible_cols / 2
    start_row := cam_row - visible_rows / 2

    for r in 0..<visible_rows {
        for c in 0..<visible_cols {
            gc := start_col + c
            gr := start_row + r
            if gc < 0 || gc >= GRID_W || gr < 0 || gr >= GRID_H do continue

            cell  := &g.cells[gr][gc]
            color := terrain_color(cell.terrain)

            px := origin_x + c * RENDER_CELL_PX
            py := origin_y + r * RENDER_CELL_PX
            rl.DrawRectangle(px, py, RENDER_CELL_PX, RENDER_CELL_PX, color)

            // Draw occupant dot
            if cell.occupant != 0 {
                dot_x := px + RENDER_CELL_PX / 2
                dot_y := py + RENDER_CELL_PX / 2
                rl.DrawPixel(dot_x, dot_y, rl.WHITE)
            }
        }
    }
}

