/*
 * creation.odin — Character creation screen (M2).
 *
 * Screen flow:
 *   Creation → Confirm → Relationship seeding → back to Residents / Simulation
 *
 * All drawing uses Raylib directly — no external UI framework.
 */

package dmls

import rl "vendor:raylib"
import "core:strings"
import "core:fmt"
import "core:mem"

// ---- Layout constants ------------------------------------------------------

SCREEN_W :: 1024
SCREEN_H ::  720

UI_PAD   :: 24
UI_LPAD  :: 64          // left margin for form fields
UI_FSIZE :: 20          // font size for body text
UI_HSIZE :: 28          // font size for headings
UI_SMALL :: 16

COL_BG      :: rl.Color{15,  15,  20,  255}
COL_PANEL   :: rl.Color{28,  28,  38,  255}
COL_ACCENT  :: rl.Color{120, 80,  200, 255}
COL_ACCENT2 :: rl.Color{200, 80,  120, 255}
COL_TEXT    :: rl.Color{220, 220, 230, 255}
COL_MUTED   :: rl.Color{130, 130, 150, 255}
COL_INPUT   :: rl.Color{40,  40,  55,  255}
COL_HOVER   :: rl.Color{60,  60,  80,  255}
COL_SELECT  :: rl.Color{90,  60,  160, 255}
COL_CONFIRM :: rl.Color{60,  160, 100, 255}

// ---- Input field -----------------------------------------------------------

InputField :: struct {
    buf    : [MAX_NAME_LEN]u8,
    len    : int,
    active : bool,
}

input_field_init :: proc(f: ^InputField) { f^ = {} }

input_field_str :: proc(f: ^InputField) -> string {
    return string(f.buf[:f.len])

/*
 * noise.odin — Seed-reproducible Perlin noise (M3).
 *
 * Classic permutation-table Perlin noise (Ken Perlin, 2002 improved version).
 * The permutation table is derived from the world seed so the same seed always
 * produces the same island.
 */

package dmls

import "core:math"

// ---- Permutation table -----------------------------------------------------

PERM_SIZE :: 256

NoiseState :: struct {
    perm : [PERM_SIZE * 2]u8,   // doubled for fast wrapping
}

noise_init :: proc(ns: ^NoiseState, seed: u64) {
    // Fill 0..255 then shuffle via LCG seeded by world seed.
    for i in 0..<PERM_SIZE {
        ns.perm[i] = u8(i)
    }
    s := seed
    for i := PERM_SIZE - 1; i > 0; i -= 1 {
        s = s * 6364136223846793005 + 1442695040888963407
        j := int((s >> 33) % u64(i + 1))
        ns.perm[i], ns.perm[j] = ns.perm[j], ns.perm[i]
    }
    for i in 0..<PERM_SIZE {
        ns.perm[i + PERM_SIZE] = ns.perm[i]
    }
}

// ---- Gradient function (Perlin 2002) ---------------------------------------

_fade :: proc(t: f64) -> f64 {
    return t * t * t * (t * (t * 6 - 15) + 10)
}

_lerp :: proc(a, b, t: f64) -> f64 {
    return a + t * (b - a)
}

_grad :: proc(hash: u8, x, y: f64) -> f64 {
    switch hash & 7 {
    case 0: return  x + y
    case 1: return -x + y
    case 2: return  x - y
    case 3: return -x - y
    case 4: return  x
    case 5: return -x
    case 6: return  y
    case 7: return -y
    }
    return 0
}

// perlin2 returns a value in [-1, 1].
perlin2 :: proc(ns: ^NoiseState, x, y: f64) -> f64 {
    xi := int(math.floor(x)) & 255
    yi := int(math.floor(y)) & 255

    xf := x - math.floor(x)
    yf := y - math.floor(y)

    u := _fade(xf)
    v := _fade(yf)

    aa := int(ns.perm[ns.perm[xi  ] + u8(yi  )])
    ab := int(ns.perm[ns.perm[xi  ] + u8(yi+1)])
    ba := int(ns.perm[ns.perm[xi+1] + u8(yi  )])
    bb := int(ns.perm[ns.perm[xi+1] + u8(yi+1)])

    x1 := _lerp(_grad(u8(aa), xf,   yf  ),
                 _grad(u8(ba), xf-1, yf  ), u)
    x2 := _lerp(_grad(u8(ab), xf,   yf-1),
                 _grad(u8(bb), xf-1, yf-1), u)
    return _lerp(x1, x2, v)
}

// fbm — fractional Brownian motion: sum of `octaves` layers.
fbm :: proc(ns: ^NoiseState, x, y: f64, octaves: int) -> f64 {
    val, amp, freq := 0.0, 1.0, 1.0
    for _ in 0..<octaves {
        val  += perlin2(ns, x * freq, y * freq) * amp
        amp  *= 0.5
        freq *= 2.0
    }
    return val
}

