/*
 * rand.odin — Randomness systems (M4).
 *
 * Four modes:
 *   1. Independent  — stateless hash, pure function of seed+index
 *   2. Dependent    — PCG-style chain; one outcome influences the next
 *   3. Weighted     — draw from a distribution by cumulative weights
 *   4. Uniform      — uniform pick from a slice (uses dependent RNG)
 */

package dmls

// ---- 1. Independent randomness ---------------------------------------------
// Pure: no state. Good for terrain events, item drops.

independent_rand :: proc(seed: u64) -> f64 {
    // Splitmix64 finaliser — avalanche the bits.
    s := seed + 0x9e3779b97f4a7c15
    s  = (s ~ (s >> 30)) * 0xbf58476d1ce4e5b9
    s  = (s ~ (s >> 27)) * 0x94d049bb133111eb
    s   = s ~ (s >> 31)
    return f64(s >> 11) / f64(1 << 53)
}

// independent_rand_range returns a uniform integer in [0, n).
independent_rand_range :: proc(seed: u64, n: u64) -> u64 {
    return u64(independent_rand(seed) * f64(n))
}

// ---- 2. Dependent (chained) randomness -------------------------------------
// PCG-style LCG. Each call advances the chain; the same seed always
// produces the same sequence.

DependentRNG :: struct {
    state : u64,
    seq   : u64,   // stream selector — survives save/load
}

dependent_rng_init :: proc(r: ^DependentRNG, seed, seq: u64) {
    r.state = 0
    r.seq   = (seq << 1) | 1   // seq must be odd
    dependent_next_u64(r)      // warm up
    r.state += seed
    dependent_next_u64(r)
}

dependent_next_u64 :: proc(r: ^DependentRNG) -> u64 {
    old   := r.state
    r.state = old * 6364136223846793005 + r.seq
    xors  := u32(((old >> 18) ~ old) >> 27)
    rot   := u32(old >> 59)
    return u64(xors >> rot | xors << ((-rot) & 31))
}

// dependent_next returns a value in [0.0, 1.0).
dependent_next :: proc(r: ^DependentRNG) -> f64 {
    return f64(dependent_next_u64(r) >> 11) / f64(1 << 53)
}

// dependent_next_range returns a uniform integer in [0, n).
dependent_next_range :: proc(r: ^DependentRNG, n: u64) -> u64 {
    return u64(dependent_next(r) * f64(n))
}

// ---- 3. Weighted randomness ------------------------------------------------
// Returns the index of the chosen option. Weights need not sum to 1.

weighted_choice_f64 :: proc(r: ^DependentRNG, weights: []f64) -> int {
    if len(weights) == 0 do return 0
    total := 0.0
    for w in weights { total += w }
    pick := dependent_next(r) * total
    cum  := 0.0
    for i, w in weights {
        cum += w
        if pick < cum do return i
    }
    return len(weights) - 1
}

weighted_choice_int :: proc(r: ^DependentRNG, weights: []int) -> int {
    if len(weights) == 0 do return 0
    total := 0
    for w in weights { total += w }
    pick := int(dependent_next_range(r, u64(total)))
    cum  := 0
    for i, w in weights {
        cum += w
        if pick < cum do return i
    }
    return len(weights) - 1
}

// ---- 4. Uniform (non-weighted) randomness ----------------------------------
// Uniform pick of an index from [0, n).

uniform_choice :: proc(r: ^DependentRNG, n: int) -> int {
    if n <= 0 do return 0
    return int(dependent_next_range(r, u64(n)))
}

