    return len(weights) - 1
}

weighted_choice_int :: proc(r: ^DependentRNG, weights: []int) -> int {
    if len(weights) == 0 do return 0
    total := 0
    for w in weights { total += w }
    pick := int(dependent_next_range(r, u64(total)))
    cum  := 0
    for i, w in weights {
        cum += w
        if pick < cum do return i
    }
    return len(weights) - 1
}

// ---- 4. Uniform (non-weighted) randomness ----------------------------------
// Uniform pick of an index from [0, n).

uniform_choice :: proc(r: ^DependentRNG, n: int) -> int {
    if n <= 0 do return 0
    return int(dependent_next_range(r, u64(n)))
}

