/*
 * relationships.odin — Relationship seeding screen (M2).
 */

package dmls

import rl "vendor:raylib"
import "core:fmt"
import "core:strings"

RelSeeding :: struct {
    new_char_id : u32,
    tags        : [MAX_RESIDENTS]RelationshipTag,
}

rel_seeding_init :: proc(s: ^RelSeeding, new_id: u32, res: ^Residents) {
    s^ = {}
    s.new_char_id = new_id
}

rel_seeding_update :: proc(s: ^RelSeeding, res: ^Residents) -> bool {
    rl.ClearBackground(COL_BG)

    rl.DrawText("Relationship Seeding", UI_LPAD, UI_PAD, UI_HSIZE, COL_TEXT)
    rl.DrawText("How does the new resident know the islanders?", UI_LPAD, UI_PAD + UI_HSIZE + 4, UI_SMALL, COL_MUTED)

    new_char := residents_find(res, s.new_char_id)
    if new_char != nil {
        name_cstr := strings.clone_to_cstring(character_name(new_char), context.temp_allocator)
        buf: [64]u8
        bs := fmt.bprintf(buf[:], "New resident: %s", name_cstr)
        buf[len(bs)] = 0
        rl.DrawText(cstring(raw_data(buf[:])), UI_LPAD, UI_PAD + UI_HSIZE + 26, UI_SMALL, COL_ACCENT)
    }

    if res.count <= 1 {
        rl.DrawText("No other residents yet — nothing to tag.",
            UI_LPAD, i32(SCREEN_H / 2), UI_FSIZE, COL_MUTED)
    } else {
        tag_labels := []cstring{"Stranger", "Acquaintance", "Friend", "Sibling", "Partner"}

        y := i32(UI_PAD + UI_HSIZE + 60)

        for i in 0..<res.count {
            c := &res.chars[i]
            if c.id == s.new_char_id do continue

            name_cstr := strings.clone_to_cstring(character_name(c), context.temp_allocator)
            rl.DrawText(name_cstr, UI_LPAD, y, UI_FSIZE, COL_TEXT)

            cx := i32(UI_LPAD + 200)
            for tag_i in 0..<len(tag_labels) {
                tw   := rl.MeasureText(tag_labels[tag_i], UI_SMALL) + 18
                rect := rl.Rectangle{f32(cx), f32(y - 2), f32(tw), 28}
                hov  := rl.CheckCollisionPointRec(rl.GetMousePosition(), rect)
                sel  := int(s.tags[i]) == tag_i
                bg   := sel ? COL_SELECT : (hov ? COL_HOVER : COL_INPUT)
                rl.DrawRectangleRec(rect, bg)
                rl.DrawRectangleLinesEx(rect, 1, sel ? COL_ACCENT : COL_MUTED)
                rl.DrawText(tag_labels[tag_i], cx + 8, y + 4, UI_SMALL, COL_TEXT)
                if hov && rl.IsMouseButtonPressed(.LEFT) {
                    s.tags[i] = RelationshipTag(tag_i)
                }
                cx += tw + 6
            }
            y += 44
        }
    }

    done_rect := rl.Rectangle{f32(UI_LPAD), f32(SCREEN_H - 80), 240, 42}
    hov := rl.CheckCollisionPointRec(rl.GetMousePosition(), done_rect)
    rl.DrawRectangleRec(done_rect, hov ? COL_CONFIRM : rl.Color{40, 120, 70, 255})
    rl.DrawText("Join the island ->", UI_LPAD + 16, SCREEN_H - 66, UI_FSIZE, COL_TEXT)

    if (hov && rl.IsMouseButtonPressed(.LEFT)) || rl.IsKeyPressed(.ENTER) {
        return true
    }
    return false
}

rel_seeding_commit :: proc(s: ^RelSeeding, res: ^Residents, engine: ^EpilogEngine) {
    for i in 0..<res.count {
        c := &res.chars[i]
        if c.id == s.new_char_id do continue
        tag := s.tags[i]
        epilog_assert_relationship(engine, s.new_char_id, c.id, tag)
        if tag == .Friend || tag == .Sibling || tag == .Partner {
            epilog_assert_relationship(engine, c.id, s.new_char_id, tag)
        }
    }
}

