// ---- Rendering -------------------------------------------------------------

// cell_px — pixel size when rendering at the given zoom.
RENDER_CELL_PX :: 3   // each grid cell = 3×3 pixels

// Render the grid into the current drawing context.
// origin_x/y: top-left pixel of the simulation view.
// view_w/h:   pixel size of the simulation panel.
grid_render :: proc(g: ^Grid, origin_x, origin_y, view_w, view_h: i32,
                    cam_col, cam_row: i32) {
    visible_cols := view_w  / RENDER_CELL_PX + 2
    visible_rows := view_h / RENDER_CELL_PX + 2

    start_col := cam_col - visible_cols / 2
    start_row := cam_row - visible_rows / 2

    for r in 0..<visible_rows {
        for c in 0..<visible_cols {
            gc := start_col + c
            gr := start_row + r
            if gc < 0 || gc >= GRID_W || gr < 0 || gr >= GRID_H do continue

            cell  := &g.cells[gr][gc]
            color := terrain_color(cell.terrain)

            px := origin_x + c * RENDER_CELL_PX
            py := origin_y + r * RENDER_CELL_PX
            rl.DrawRectangle(px, py, RENDER_CELL_PX, RENDER_CELL_PX, color)

            // Draw occupant dot
            if cell.occupant != 0 {
                dot_x := px + RENDER_CELL_PX / 2
                dot_y := py + RENDER_CELL_PX / 2
                rl.DrawPixel(dot_x, dot_y, rl.WHITE)
            }
        }
    }
}

